package com.fluxisai.subscription;
import java.math.BigDecimal; import java.time.*; import java.util.UUID; import jakarta.persistence.*;
@Entity @Table(name="subscriptions") public class Subscription { @Id @GeneratedValue(strategy=GenerationType.UUID) private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(nullable=false,length=200) private String name; @Column(nullable=false,length=200) private String provider; @Column(nullable=false,precision=19,scale=2) private BigDecimal amount; @Column(nullable=false,length=3) private String currency; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private SubscriptionPeriodicity periodicity; @Column(name="next_charge_date") private LocalDate nextChargeDate; @Column(name="renewal_date") private LocalDate renewalDate; @Enumerated(EnumType.STRING) @Column(nullable=false,length=20) private SubscriptionStatus status; @Column(length=120) private String category; @Column(columnDefinition="text") private String notes; @Column(name="management_url",length=2048) private String managementUrl; @Column(name="created_at",nullable=false,updatable=false) private OffsetDateTime createdAt; @Column(name="updated_at",nullable=false) private OffsetDateTime updatedAt;
 protected Subscription(){} public Subscription(UUID u,String n,String p,BigDecimal a,String c,SubscriptionPeriodicity period,LocalDate next,LocalDate renewal,SubscriptionStatus s,String cat,String notes,String url){userId=u;name=n;provider=p;amount=a;currency=c;periodicity=period;nextChargeDate=next;renewalDate=renewal;status=s==null?SubscriptionStatus.ACTIVE:s;category=cat;this.notes=notes;managementUrl=url;} public void update(String n,String p,BigDecimal a,String c,SubscriptionPeriodicity period,LocalDate next,LocalDate renewal,SubscriptionStatus s,String cat,String notes,String url){name=n;provider=p;amount=a;currency=c;periodicity=period;nextChargeDate=next;renewalDate=renewal;status=s==null?SubscriptionStatus.ACTIVE:s;category=cat;this.notes=notes;managementUrl=url;} @PrePersist void create(){var n=OffsetDateTime.now(ZoneOffset.UTC);createdAt=n;updatedAt=n;} @PreUpdate void updateTime(){updatedAt=OffsetDateTime.now(ZoneOffset.UTC);}
 public UUID getId(){return id;} public UUID getUserId(){return userId;} public String getName(){return name;} public String getProvider(){return provider;} public BigDecimal getAmount(){return amount;} public String getCurrency(){return currency;} public SubscriptionPeriodicity getPeriodicity(){return periodicity;} public LocalDate getNextChargeDate(){return nextChargeDate;} public LocalDate getRenewalDate(){return renewalDate;} public SubscriptionStatus getStatus(){return status;} public String getCategory(){return category;} public String getNotes(){return notes;} public String getManagementUrl(){return managementUrl;} public OffsetDateTime getCreatedAt(){return createdAt;} public OffsetDateTime getUpdatedAt(){return updatedAt;}
}
